import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Card, Button, Alert, api } from '../App';

const MAX_SLOTS = 5;

// ── Column filter dropdown ───────────────────────────────────────────────────
const ColFilter = ({ label, options, selected, onChange }) => {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, []);
  const toggle = v => onChange(selected.includes(v) ? selected.filter(x => x !== v) : [...selected, v]);
  return (
    <div ref={ref} style={{ position: 'relative', display: 'inline-block' }}>
      <div onClick={() => setOpen(o => !o)} style={{ cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 4, userSelect: 'none', whiteSpace: 'nowrap' }}>
        <span>{label}</span>
        {selected.length > 0
          ? <span style={{ background: '#f59e0b', color: '#fff', borderRadius: 99, fontSize: 10, padding: '1px 5px', fontWeight: 700 }}>{selected.length}</span>
          : <span style={{ fontSize: 9, opacity: 0.6 }}>▼</span>}
      </div>
      {open && (
        <div style={{ position: 'absolute', top: '110%', left: 0, background: '#fff', border: '1px solid #e2e8f0', borderRadius: 8, zIndex: 200, boxShadow: '0 8px 24px rgba(0,0,0,0.15)', minWidth: 180, maxHeight: 260, overflowY: 'auto' }}>
          <div style={{ padding: '7px 12px', borderBottom: '1px solid #f0f4f8', display: 'flex', justifyContent: 'space-between', position: 'sticky', top: 0, background: '#fff' }}>
            <span style={{ fontSize: 11, color: '#888', fontWeight: 700 }}>Filter {label}</span>
            <button onMouseDown={() => onChange([])} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: 11, color: '#c0392b', fontWeight: 700 }}>Clear</button>
          </div>
          {options.map(opt => (
            <div key={opt} onMouseDown={() => toggle(opt)}
              style={{ padding: '7px 12px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 8, background: selected.includes(opt) ? '#eff6ff' : '#fff', fontSize: 13, color: '#1a2533', borderBottom: '1px solid #f9fafb' }}>
              <div style={{ width: 15, height: 15, borderRadius: 3, flexShrink: 0, border: `2px solid ${selected.includes(opt) ? '#1a3c5e' : '#cbd5e0'}`, background: selected.includes(opt) ? '#1a3c5e' : '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                {selected.includes(opt) && <span style={{ color: '#fff', fontSize: 9, fontWeight: 700 }}>✓</span>}
              </div>
              <span style={{ fontWeight: selected.includes(opt) ? 600 : 400 }}>{opt}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

// ── Editable P-slot cell ─────────────────────────────────────────────────────
// Tab moves cursor to NEXT P column (right), Enter confirms
const SlotCell = ({ catalogueId, slotIdx, value, onChange, allParties, filteredLots, rowIdx }) => {
  const [editing, setEditing]   = useState(false);
  const [draft,   setDraft]     = useState('');
  const [sugg,    setSugg]      = useState([]);
  const inputRef = useRef(null);

  const getSugg = v => !v ? [] : allParties.filter(p => p.party_code.startsWith(v.toUpperCase())).slice(0, 5);

  const startEdit = () => {
    setDraft(value?.party_code || '');
    setEditing(true);
    setTimeout(() => { inputRef.current?.focus(); inputRef.current?.select(); }, 20);
  };

  const commit = useCallback((codeOverride) => {
    const c = (codeOverride ?? draft).trim().toUpperCase();
    setEditing(false); setSugg([]);
    if (!c) { onChange(null); return; }
    const p = allParties.find(x => x.party_code === c);
    onChange(p ? { party_id: p.id, party_name: p.party_name, party_code: p.party_code } : null);
  }, [draft, allParties, onChange]);

  // Focus the next cell in P-slot order: right across columns, then next row
  const focusNext = useCallback(() => {
    // Try next slot in same row
    const nextSlot = slotIdx + 1;
    if (nextSlot < MAX_SLOTS) {
      const el = document.querySelector(`[data-slot="${catalogueId}-${nextSlot}"]`);
      el?.click();
    } else {
      // Move to P1 of next visible row
      const nextRow = filteredLots[rowIdx + 1];
      if (nextRow) {
        const el = document.querySelector(`[data-slot="${nextRow.catalogue_id}-0"]`);
        el?.click();
      }
    }
  }, [catalogueId, slotIdx, filteredLots, rowIdx]);

  const handleKey = e => {
    if (e.key === 'Enter')   { e.preventDefault(); commit(); }
    if (e.key === 'Tab')     { e.preventDefault(); commit(); setTimeout(focusNext, 60); }
    if (e.key === 'Escape')  { setEditing(false); setSugg([]); }
    if (e.key === 'Backspace' && draft === '') { onChange(null); setEditing(false); }
  };

  if (editing) {
    return (
      <div style={{ position: 'relative', display: 'inline-block' }}>
        <input ref={inputRef}
          value={draft}
          onChange={e => { const v = e.target.value.toUpperCase(); setDraft(v); setSugg(getSugg(v)); }}
          onKeyDown={handleKey}
          onBlur={() => setTimeout(() => { commit(); setSugg([]); }, 160)}
          maxLength={5}
          style={{ width: 58, padding: '3px 5px', border: '2px solid #1a3c5e', borderRadius: 5, fontSize: 11, fontFamily: 'monospace', textTransform: 'uppercase', outline: 'none' }}
        />
        {sugg.length > 0 && (
          <div style={{ position: 'absolute', top: '100%', left: 0, background: '#fff', border: '1px solid #e2e8f0', borderRadius: 6, zIndex: 999, boxShadow: '0 4px 12px rgba(0,0,0,0.1)', minWidth: 160 }}>
            {sugg.map(s => (
              <div key={s.id}
                onMouseDown={e => { e.preventDefault(); commit(s.party_code); }}
                style={{ padding: '6px 10px', cursor: 'pointer', fontSize: 12, borderBottom: '1px solid #f0f4f8' }}
                onMouseEnter={e => e.currentTarget.style.background = '#f0f8ff'}
                onMouseLeave={e => e.currentTarget.style.background = '#fff'}>
                <b style={{ color: '#1a3c5e' }}>{s.party_code}</b> — {s.party_name}
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  return (
    <div
      data-slot={`${catalogueId}-${slotIdx}`}
      onClick={startEdit}
      title={`P${slotIdx + 1}: Click or Tab to edit`}
      style={{ minWidth: 52, height: 26, padding: '2px 7px', borderRadius: 99, cursor: 'pointer', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', transition: 'all 0.1s',
        background: value ? '#1a3c5e' : 'transparent',
        border: value ? 'none' : '1.5px dashed #d1d5db' }}>
      {value
        ? <span style={{ color: '#fff', fontSize: 11, fontWeight: 700 }}>{value.party_code}</span>
        : <span style={{ color: '#d1d5db', fontSize: 10 }}>—</span>
      }
    </div>
  );
};

// ── Main MarkingPage ─────────────────────────────────────────────────────────
export default function MarkingPage() {
  const [allParties,  setAllParties]  = useState([]);
  const [saleNos,     setSaleNos]     = useState([]);
  const [selParties,  setSelParties]  = useState([]);
  const [saleNo,      setSaleNo]      = useState('');
  const [partySearch, setPartySearch] = useState('');

  const [allLots,    setAllLots]    = useState([]);
  const [lotSlots,   setLotSlots]   = useState({});
  const [partyOrder, setPartyOrder] = useState([]);
  const [skipRows,   setSkipRows]   = useState({});
  const [loading,    setLoading]    = useState(false);
  const [marking,    setMarking]    = useState(false);
  const [saving,     setSaving]     = useState(false);
  const [alert,      setAlert]      = useState(null);

  const [filterGrades,   setFilterGrades]   = useState([]);
  const [filterGardens,  setFilterGardens]  = useState([]);
  const [filterBrokers,  setFilterBrokers]  = useState([]);
  const [searchLot,      setSearchLot]      = useState('');
  const [showMarkedOnly, setShowMarkedOnly] = useState(false);
  const [aiSuggestions, setAiSuggestions]   = useState([]);
  const [aiWeeks,       setAiWeeks]         = useState(2);
  const [aiParty,       setAiParty]         = useState('');
  const [aiLoading,     setAiLoading]       = useState(false);
  const [dupAlerts,     setDupAlerts]       = useState({}); // catalogue_id -> message

  useEffect(() => {
    Promise.all([
      api.get('/parties').catch(() => ({ data: [] })),
      api.get('/import/sale-numbers').catch(() => ({ data: [] }))
    ]).then(([p, s]) => { setAllParties(p.data); setSaleNos(s.data); });
  }, []);

  const loadAllLots = useCallback(async (sale) => {
    if (!sale) return;
    setLoading(true);
    try {
      const r = await api.post('/marking/preview', { party_ids: [], sale_no: sale });
      setAllLots(r.data.lots || []);
      const slots = {};
      (r.data.lots || []).forEach(l => { slots[l.catalogue_id] = Array(MAX_SLOTS).fill(null); });
      setLotSlots(slots);
      setPartyOrder([]);
      setFilterGrades([]); setFilterGardens([]); setFilterBrokers([]); setSearchLot('');
      setSelParties([]);
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setLoading(false); }
  }, []);

  const handleSaleChange = s => { setSaleNo(s); if (s) loadAllLots(s); };

  const markLots = async () => {
    if (!selParties.length || !saleNo) { setAlert({ msg: 'Select parties first', type: 'error' }); return; }
    setMarking(true); setAlert(null);
    try {
      const r = await api.post('/marking/preview', { party_ids: selParties.map(p => p.id), sale_no: saleNo });
      setPartyOrder(r.data.parties || []);
      const lots = r.data.lots || [];
      setLotSlots(prev => {
        const next = { ...prev };
        lots.forEach(lot => {
          const eligible = lot.party_slots_array || [];
          const newSlots = Array(MAX_SLOTS).fill(null);
          eligible.slice(0, MAX_SLOTS).forEach((p, i) => { newSlots[i] = p; });
          next[lot.catalogue_id] = newSlots;
        });
        return next;
      });
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setMarking(false); }
  };

  const toggleParty = p =>
    setSelParties(prev => prev.find(x => x.id === p.id)
      ? prev.filter(x => x.id !== p.id)
      : [...prev, { id: p.id, party_name: p.party_name, party_code: p.party_code }]
    );

  const filteredParties = allParties.filter(p =>
    p.party_name.toLowerCase().includes(partySearch.toLowerCase()) ||
    p.party_code.toLowerCase().includes(partySearch.toLowerCase())
  );

  // Select All / Deselect All
  const selectAllParties  = () => setSelParties(filteredParties.map(p => ({ id: p.id, party_name: p.party_name, party_code: p.party_code })));
  const deselectAllParties = () => setSelParties([]);

  const updateSlot = (catalogueId, slotIdx, value) => {
    setLotSlots(prev => {
      const arr = [...(prev[catalogueId] || Array(MAX_SLOTS).fill(null))];
      arr[slotIdx] = value;
      return { ...prev, [catalogueId]: arr };
    });

    // Check for duplicate Broker+Garden+Grade when a party is manually assigned
    if (value?.party_id && saleNo) {
      const lot = allLots.find(l => l.catalogue_id === catalogueId);
      if (lot) {
        api.post('/marking/check-duplicate', {
          party_id: value.party_id, sale_no: saleNo,
          garden: lot.garden, grade: lot.grade
        }).then(r => {
          if (r.data.exists) {
            setDupAlerts(prev => ({
              ...prev,
              [catalogueId]: `⚠️ ${value.party_code} already marked for ${lot.garden}/${lot.grade}. Added as duplicate — allowed.`
            }));
            setTimeout(() => setDupAlerts(prev => { const n={...prev}; delete n[catalogueId]; return n; }), 5000);
          }
        }).catch(() => {});
      }
    }
  };

  const loadAiSuggestions = async () => {
    if (!aiParty || !saleNo) return;
    setAiLoading(true);
    try {
      const r = await api.get(`/marking/ai-suggest?party_id=${aiParty}&weeks=${aiWeeks}`);
      setAiSuggestions(r.data.suggestions || []);
    } catch (e) { console.error(e); }
    finally { setAiLoading(false); }
  };

  const save = async () => {
    const markedLots = allLots
      .filter(l => !skipRows[l.catalogue_id] && (lotSlots[l.catalogue_id] || []).some(s => s?.party_id))
      .map(l => ({ ...l, final_slots: (lotSlots[l.catalogue_id] || []).filter(Boolean), final_price: l.suggested_price }));
    if (!markedLots.length) { setAlert({ msg: 'No markings to save', type: 'warning' }); return; }
    setSaving(true);
    try {
      const r = await api.post('/marking/save', { markings: markedLots, sale_no: saleNo });
      setAlert({ msg: `✅ ${r.data.saved} markings saved.${r.data.duplicates ? ` ${r.data.duplicates} skipped.` : ''}`, type: 'success' });
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setSaving(false); }
  };

  const gradesOpts  = [...new Set(allLots.map(r => r.grade).filter(Boolean))].sort();
  const gardensOpts = [...new Set(allLots.map(r => r.garden).filter(Boolean))].sort();
  const brokersOpts = [...new Set(allLots.map(r => r.broker).filter(Boolean))].sort();

  const filteredLots = allLots.filter(row => {
    if (filterGrades.length  > 0 && !filterGrades.includes(row.grade))   return false;
    if (filterGardens.length > 0 && !filterGardens.includes(row.garden)) return false;
    if (filterBrokers.length > 0 && !filterBrokers.includes(row.broker)) return false;
    if (searchLot && !(row.lot_no || '').toLowerCase().includes(searchLot.toLowerCase())) return false;
    if (showMarkedOnly && !(lotSlots[row.catalogue_id] || []).some(s => s?.party_id)) return false;
    return true;
  });

  const markedCount = allLots.filter(l => !skipRows[l.catalogue_id] && (lotSlots[l.catalogue_id] || []).some(s => s?.party_id)).length;
  const hasFilters  = filterGrades.length > 0 || filterGardens.length > 0 || filterBrokers.length > 0 || searchLot || showMarkedOnly;
  const clearFilters = () => { setFilterGrades([]); setFilterGardens([]); setFilterBrokers([]); setSearchLot(''); setShowMarkedOnly(false); };

  const fmtDate = d => { try { const dt = new Date(d); return `${String(dt.getDate()).padStart(2,'0')}/${String(dt.getMonth()+1).padStart(2,'0')}`; } catch { return '—'; } };
  const fmtRate = row => {
    const mn = row.min_deal_price, mx = row.max_deal_price;
    if (!mn && !mx) return '—';
    if (mn && mx && Math.abs(parseFloat(mn) - parseFloat(mx)) > 0.5) return `${Number(mn).toFixed(0)}-${Number(mx).toFixed(0)}`;
    return `${Number(mn || mx).toFixed(0)}/-`;
  };

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>✅ Create Markings</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>Select sale → all lots load. Pick parties → Mark Lots fills P1–P5. Click any slot to edit (Tab=next column, Enter=confirm).</p>

      {alert && <Alert msg={alert.msg} type={alert.type} />}

      {/* ── CONTROL PANEL ── */}
      <Card style={{ marginBottom: 16, padding: 16 }}>
        {/* Sale */}
        <div style={{ display: 'flex', gap: 12, alignItems: 'flex-end', flexWrap: 'wrap', marginBottom: 16 }}>
          <div>
            <label style={{ display: 'block', fontSize: 11, fontWeight: 700, color: '#555', marginBottom: 4, textTransform: 'uppercase', letterSpacing: 0.4 }}>Sale Number *</label>
            <select value={saleNo} onChange={e => handleSaleChange(e.target.value)}
              style={{ padding: '8px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 220 }}>
              <option value="">Select sale to load all lots…</option>
              {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
            </select>
          </div>
          {allLots.length > 0 && (
            <div style={{ fontSize: 12, color: '#555' }}>
              <b>{allLots.length}</b> lots · <b style={{ color: '#1a7a4a' }}>{filteredLots.length}</b> shown · <b style={{ color: '#1a7a4a' }}>{markedCount}</b> marked
              {hasFilters && <button onClick={clearFilters} style={{ marginLeft: 10, fontSize: 11, color: '#c0392b', background: 'none', border: '1px solid #fecaca', borderRadius: 4, padding: '2px 7px', cursor: 'pointer' }}>✕ Clear filters</button>}
              {/* Show Marked Only toggle */}
              <button onClick={() => setShowMarkedOnly(v => !v)}
                style={{ marginLeft: 10, fontSize: 11, padding: '3px 10px', borderRadius: 4, cursor: 'pointer', fontWeight: 600,
                  background: showMarkedOnly ? '#1a7a4a' : '#f0fdf4',
                  color: showMarkedOnly ? '#fff' : '#1a7a4a',
                  border: `1.5px solid ${showMarkedOnly ? '#1a7a4a' : '#bbf7d0'}` }}>
                {showMarkedOnly ? '✓ Marked Only' : '🔍 Show Marked Only'}
              </button>
            </div>
          )}
          {markedCount > 0 && (
            <Button onClick={save} disabled={saving} variant="success">{saving ? 'Saving…' : `💾 Save ${markedCount} Markings`}</Button>
          )}
        </div>

        {/* Party selector */}
        {allLots.length > 0 && (
          <>
            <div style={{ fontSize: 11, fontWeight: 700, color: '#444', textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 8 }}>
              Select Parties — click to select/deselect, then click Mark Lots
            </div>
            <div style={{ display: 'flex', gap: 8, marginBottom: 8, alignItems: 'center', flexWrap: 'wrap' }}>
              <input value={partySearch} onChange={e => setPartySearch(e.target.value)} placeholder="Search parties…"
                style={{ padding: '6px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 12, width: 180 }} />
              <button onClick={selectAllParties}
                style={{ padding: '5px 12px', borderRadius: 6, border: '1.5px solid #1a3c5e', background: '#1a3c5e', color: '#fff', fontSize: 12, fontWeight: 600, cursor: 'pointer' }}>
                ✓ Select All
              </button>
              <button onClick={deselectAllParties}
                style={{ padding: '5px 12px', borderRadius: 6, border: '1.5px solid #e2e8f0', background: '#f9fafb', color: '#555', fontSize: 12, fontWeight: 600, cursor: 'pointer' }}>
                ✕ Deselect All
              </button>
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, maxHeight: 130, overflowY: 'auto', marginBottom: 10, padding: '4px 0' }}>
              {filteredParties.map(p => {
                const sel = !!selParties.find(x => x.id === p.id);
                const idx = selParties.findIndex(x => x.id === p.id);
                return (
                  <div key={p.id} onClick={() => toggleParty(p)}
                    style={{ padding: '5px 12px', borderRadius: 20, cursor: 'pointer', fontSize: 12, fontWeight: 600, userSelect: 'none',
                      background: sel ? '#1a3c5e' : '#f0f4f8', color: sel ? '#fff' : '#555',
                      border: `1.5px solid ${sel ? '#1a3c5e' : '#e2e8f0'}`, display: 'inline-flex', alignItems: 'center', gap: 5 }}>
                    {sel && <span style={{ background: 'rgba(255,255,255,0.25)', borderRadius: 99, padding: '0 5px', fontSize: 10 }}>P{idx + 1}</span>}
                    [{p.party_code}] {p.party_name}
                  </div>
                );
              })}
            </div>
            {selParties.length > 0 && (
              <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                <Button onClick={markLots} disabled={marking || !saleNo} variant="primary">
                  {marking ? '⏳ Marking…' : '🎯 Mark Lots'}
                </Button>
                <button onClick={deselectAllParties} style={{ padding: '6px 12px', borderRadius: 6, border: '1.5px solid #e2e8f0', background: '#f9fafb', color: '#555', fontSize: 12, cursor: 'pointer' }}>
                  Clear selection
                </button>
                <span style={{ fontSize: 11, color: '#888' }}>
                  {selParties.length} selected → {selParties.map((p, i) => `P${i + 1}:${p.party_code}`).join(' · ')}
                </span>
              </div>
            )}

            {/* AI Suggestion Panel */}
            {allLots.length > 0 && (
              <div style={{ marginTop: 14, padding: '12px 16px', background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 8 }}>
                <div style={{ fontSize: 12, fontWeight: 700, color: '#92400e', marginBottom: 8 }}>💡 AI Marking Suggestions — based on historical markings</div>
                <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', marginBottom: aiSuggestions.length > 0 ? 10 : 0 }}>
                  <select value={aiParty} onChange={e => setAiParty(e.target.value)}
                    style={{ padding: '6px 10px', border: '1.5px solid #fcd34d', borderRadius: 6, fontSize: 12, minWidth: 180 }}>
                    <option value="">Select party for AI suggest…</option>
                    {allParties.map(p => <option key={p.id} value={p.id}>[{p.party_code}] {p.party_name}</option>)}
                  </select>
                  <select value={aiWeeks} onChange={e => setAiWeeks(Number(e.target.value))}
                    style={{ padding: '6px 10px', border: '1.5px solid #fcd34d', borderRadius: 6, fontSize: 12 }}>
                    <option value={2}>Last 2 weeks</option>
                    <option value={4}>Last 4 weeks</option>
                  </select>
                  <button onClick={loadAiSuggestions} disabled={aiLoading || !aiParty}
                    style={{ padding: '6px 14px', background: '#f59e0b', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontWeight: 700, fontSize: 12 }}>
                    {aiLoading ? '⏳…' : '🔍 Suggest'}
                  </button>
                  {aiSuggestions.length > 0 && <button onClick={() => setAiSuggestions([])} style={{ fontSize: 11, background: 'none', border: 'none', cursor: 'pointer', color: '#888' }}>✕ Clear</button>}
                </div>
                {aiSuggestions.length > 0 && (
                  <div style={{ overflowX: 'auto' }}>
                    <table style={{ fontSize: 12, borderCollapse: 'collapse', width: '100%' }}>
                      <thead>
                        <tr style={{ background: '#fef3c7' }}>
                          {['Garden','Grade','Broker','Times Marked','Avg Price','Price Range','Confidence'].map(h => (
                            <th key={h} style={{ padding: '5px 10px', textAlign: 'left', fontWeight: 700, color: '#92400e' }}>{h}</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {aiSuggestions.map((s, i) => (
                          <tr key={i} style={{ borderBottom: '1px solid #fde68a', background: i%2===0?'#fffbeb':'#fef9e7' }}>
                            <td style={{ padding: '5px 10px', fontWeight: 700, color: '#1a3c5e' }}>{s.garden}</td>
                            <td style={{ padding: '5px 10px' }}><span style={{ background: '#dbeafe', color: '#1e40af', padding: '1px 7px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{s.grade}</span></td>
                            <td style={{ padding: '5px 10px', color: '#555' }}>{s.broker}</td>
                            <td style={{ padding: '5px 10px', textAlign: 'center', fontWeight: 700 }}>{s.frequency}×</td>
                            <td style={{ padding: '5px 10px', fontWeight: 600, color: '#1a7a4a' }}>{s.avg_price ? `₹${s.avg_price}` : '—'}</td>
                            <td style={{ padding: '5px 10px' }}>{s.price_range}</td>
                            <td style={{ padding: '5px 10px' }}>
                              <span style={{ padding: '1px 8px', borderRadius: 99, fontSize: 11, fontWeight: 700,
                                background: s.confidence==='High'?'#dcfce7':s.confidence==='Medium'?'#fef9c3':'#fee2e2',
                                color: s.confidence==='High'?'#166534':s.confidence==='Medium'?'#92400e':'#991b1b' }}>
                                {s.confidence}
                              </span>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            )}
          </>
        )}
      </Card>

      {/* ── LOTS TABLE ── */}
      {allLots.length > 0 && (
        <Card style={{ padding: 0, overflow: 'hidden' }}>
          <div style={{ padding: '10px 16px', background: '#1a3c5e', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ fontWeight: 700, fontSize: 14 }}>
              All Lots — Sale #{saleNo}
              {hasFilters && <span style={{ fontSize: 11, fontWeight: 400, marginLeft: 10, opacity: 0.8 }}>({filteredLots.length} of {allLots.length} shown)</span>}
            </div>
            <div style={{ fontSize: 11, opacity: 0.8 }}>Click slot to edit · Tab=next P column · Enter=confirm · Backspace=clear</div>
          </div>

          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr style={{ background: '#234d78', color: '#fff' }}>
                  <th style={{ padding: '8px 6px', textAlign: 'center', width: 40 }}>Skip</th>
                  {[1,2,3,4,5].map(n => (
                    <th key={n} style={{ padding: '6px 4px', textAlign: 'center', background: '#1a3c5e', minWidth: 52, fontSize: 11 }}>P{n}</th>
                  ))}
                  <th style={{ padding: '8px 6px', textAlign: 'left', fontSize: 11 }}>
                    <ColFilter label="Bro" options={brokersOpts} selected={filterBrokers} onChange={setFilterBrokers} />
                  </th>
                  <th style={{ padding: '8px 6px', textAlign: 'left', fontSize: 11 }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                      <span>Lot</span>
                      <input value={searchLot} onChange={e => setSearchLot(e.target.value)} onClick={e => e.stopPropagation()} placeholder="Search…"
                        style={{ width: 62, padding: '2px 4px', border: '1px solid rgba(255,255,255,0.3)', borderRadius: 4, fontSize: 10, background: 'rgba(255,255,255,0.15)', color: '#fff', outline: 'none' }} />
                    </div>
                  </th>
                  <th style={{ padding: '8px 6px', textAlign: 'left', minWidth: 110 }}>
                    <ColFilter label="Garden" options={gardensOpts} selected={filterGardens} onChange={setFilterGardens} />
                  </th>
                  <th style={{ padding: '8px 6px', textAlign: 'left', minWidth: 55 }}>
                    <ColFilter label="Grd" options={gradesOpts} selected={filterGrades} onChange={setFilterGrades} />
                  </th>
                  <th style={{ padding: '8px 6px', textAlign: 'right', minWidth: 90, fontSize: 11 }}>Rate (Min-Max)</th>
                  <th style={{ padding: '8px 6px', textAlign: 'left', fontSize: 11 }}>Invoice</th>
                  <th style={{ padding: '8px 6px', textAlign: 'left', minWidth: 100, fontSize: 11 }}>Origin</th>
                  <th style={{ padding: '8px 6px', textAlign: 'right', fontSize: 11 }}>Qty</th>
                  <th style={{ padding: '8px 6px', textAlign: 'right', fontSize: 11 }}>NWt</th>
                  <th style={{ padding: '8px 6px', textAlign: 'center', fontSize: 11 }}>GP Dt</th>
                </tr>
              </thead>
              <tbody>
                {filteredLots.length === 0 ? (
                  <tr><td colSpan={14} style={{ padding: 24, textAlign: 'center', color: '#aaa' }}>
                    No lots match filters. <button onClick={clearFilters} style={{ color: '#1a3c5e', background: 'none', border: 'none', cursor: 'pointer', textDecoration: 'underline' }}>Clear</button>
                  </td></tr>
                ) : filteredLots.map((row, rowIdx) => {
                  const skip     = !!skipRows[row.catalogue_id];
                  const slots    = lotSlots[row.catalogue_id] || Array(MAX_SLOTS).fill(null);
                  const hasSlot  = slots.some(s => s?.party_id);

                  return (
                    <React.Fragment key={row.catalogue_id}>
                    <tr
                      style={{ borderBottom: dupAlerts[row.catalogue_id] ? 'none' : '1px solid #f0f4f8',
                        background: skip ? '#fff5f5' : hasSlot ? (rowIdx % 2 === 0 ? '#f0fdf4' : '#e8faf0') : (rowIdx % 2 === 0 ? '#fff' : '#fafbfc'),
                        opacity: skip ? 0.4 : 1 }}>
                      <td style={{ padding: '4px 6px', textAlign: 'center' }}>
                        <input type="checkbox" checked={skip} onChange={() => setSkipRows(s => ({ ...s, [row.catalogue_id]: !s[row.catalogue_id] }))} />
                      </td>
                      {slots.map((slot, si) => (
                        <td key={si} style={{ padding: '3px 3px', textAlign: 'center' }}>
                          <SlotCell
                            catalogueId={row.catalogue_id}
                            slotIdx={si}
                            value={slot}
                            onChange={v => updateSlot(row.catalogue_id, si, v)}
                            allParties={allParties}
                            filteredLots={filteredLots}
                            rowIdx={rowIdx}
                          />
                        </td>
                      ))}
                      <td style={{ padding: '4px 6px', fontWeight: 600, color: '#555', fontSize: 11 }}>{row.broker}</td>
                      <td style={{ padding: '4px 6px', fontFamily: 'monospace', fontSize: 11, color: '#1a3c5e', fontWeight: 700 }}>{row.lot_no}</td>
                      <td style={{ padding: '4px 6px', fontWeight: 700, color: '#1a3c5e', maxWidth: 120, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontSize: 12 }} title={row.garden}>{row.garden}</td>
                      <td style={{ padding: '4px 4px' }}>
                        <span style={{ background: '#dbeafe', color: '#1e40af', padding: '1px 6px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{row.grade}</span>
                      </td>
                      {/* Rate BEFORE Invoice/Origin — matches header order */}
                      <td style={{ padding: '4px 6px', textAlign: 'right', fontWeight: 600, color: '#1a3c5e', fontSize: 11 }}>{fmtRate(row)}</td>
                      <td style={{ padding: '4px 6px', fontFamily: 'monospace', fontSize: 10, color: '#999' }}>{row.invoice || '—'}</td>
                      <td style={{ padding: '4px 6px', fontSize: 10, color: '#777', maxWidth: 100, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={row.origin}>{row.origin || '—'}</td>
                      <td style={{ padding: '4px 6px', textAlign: 'right', fontWeight: 600, fontSize: 11 }}>{row.bags || '—'}</td>
                      <td style={{ padding: '4px 6px', textAlign: 'right', fontSize: 11 }}>{row.net_wt || '—'}</td>
                      <td style={{ padding: '4px 6px', textAlign: 'center', fontSize: 11, color: '#888' }}>{fmtDate(row.gp_date)}</td>
                    </tr>
                    {dupAlerts[row.catalogue_id] && (
                      <tr>
                        <td colSpan={16} style={{ padding: '3px 12px', background: '#fffbeb', borderBottom: '1px solid #f0f4f8' }}>
                          <span style={{ fontSize: 11, color: '#92400e', fontWeight: 600 }}>{dupAlerts[row.catalogue_id]}</span>
                        </td>
                      </tr>
                    )}
                    </React.Fragment>
                  );
                })}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {!saleNo && <Card style={{ textAlign: 'center', padding: 40, color: '#aaa' }}>Select a Sale Number above to load all catalogue lots</Card>}
      {saleNo && loading && <Card style={{ textAlign: 'center', padding: 40, color: '#888' }}>⏳ Loading lots…</Card>}
    </div>
  );
}
